 "content": "def transform(grid):
    """Restore the symmetric background hidden by color 2 patches."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            orbit = {(r, c), (h - 1 - r, c), (r, w - 1 - c), (h - 1 - r, w - 1 - c)}
            known = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 2]
            if not known:
                raise ValueError(f"No known symmetric cell for {(r, c)}")
            if any(v != known[0] for v in known):
                raise ValueError(f"Symmetry conflict at {(r, c)}: {known}")
            out[r][c] = known[0]
    return out
